(async () => {
  const logos = {
    'hexagone': '',
    'icrc': '',
    'ocha': '',
    'prefectures-regions': '',
    'tf1-info': '',
    'today-mercure': '',
    'tv4-international': '',
  };
  const zones = await (await fetch('/api/zones')).json();
  const z = zones.find((x) => x.name === 'delattre-26');
  for (const [hote, b64] of Object.entries(logos)) {
    const i = z.instances.find((i) => String(i.url || '').startsWith(hote + '.'));
    if (!i) { console.log('✗ ' + hote + ' : instance introuvable'); continue; }
    const r = await fetch('/api/zones/delattre-26/instances/' + i.id + '/icon/upload', { method: 'POST', headers: { 'Content-Type': 'image/webp' }, body: Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)) });
    console.log((r.ok ? '✓ ' : '✗ ') + i.label + ' (' + i.id + ') : ' + r.status);
  }
  console.log('Terminé : rechargez la page (F5).');
})();
